import type { DeployPlan } from "@opscrew/plan-schema";

/** First lines of every root-module file. */
export const ROOT_HEADER = [
  "# Generated by OpsCrew from opscrew/plan.yaml. You own this code, but `opscrew provision`",
  "# regenerates this file; change the plan (or the vendored modules) instead.",
].join("\n");

/** True when the plan's DNS is a domain on Cloudflare. */
export function usesCloudflare(plan: DeployPlan): boolean {
  return plan.dns.provider === "cloudflare" && plan.dns.domain !== undefined;
}

/** A Terraform provider requirement: local name, registry source and version constraint. */
export interface ProviderRequirement {
  name: string;
  source: string;
  version: string;
}

export const CLOUDFLARE_PROVIDER: ProviderRequirement = {
  name: "cloudflare",
  source: "cloudflare/cloudflare",
  version: "~> 5.27",
};

/** `versions.tf` requiring `providers` in order, with the local backend. */
export function versionsTf(providers: readonly ProviderRequirement[]): string {
  return [
    ROOT_HEADER,
    "",
    "terraform {",
    '  required_version = ">= 1.6.0"',
    "",
    "  required_providers {",
    ...providers.flatMap(({ name, source, version }) => [
      `    ${name} = {`,
      `      source  = "${source}"`,
      `      version = "${version}"`,
      "    }",
    ]),
    "  }",
    "",
    "  # State lives outside the repository; OpsCrew passes the path with -backend-config at init.",
    '  backend "local" {}',
    "}",
    "",
  ].join("\n");
}

/** The Cloudflare provider block of `main.tf` (token from the environment). */
export const CLOUDFLARE_PROVIDER_BLOCK = [
  "# Token from the CLOUDFLARE_API_TOKEN environment variable.",
  'provider "cloudflare" {}',
  "",
];

/** `  name = value` lines with the `=` signs aligned, as `terraform fmt` writes them. */
export function alignedArguments(args: readonly (readonly [string, string])[]): string[] {
  const width = Math.max(...args.map(([name]) => name.length));
  return args.map(([name, value]) => `  ${name.padEnd(width)} = ${value}`);
}

export interface VariableSpec {
  name: string;
  type: string;
  description: string;
  /** HCL literal; variables with a default are never written to `terraform.tfvars.json`. */
  default?: string;
}

/** `variables.tf` declaring `specs` in order. */
export function variablesTf(specs: readonly VariableSpec[]): string {
  const blocks = specs.map((v) =>
    [
      `variable "${v.name}" {`,
      `  description = ${JSON.stringify(v.description)}`,
      `  type        = ${v.type}`,
      ...(v.default === undefined ? [] : [`  default     = ${v.default}`]),
      "}",
    ].join("\n"),
  );
  return `${ROOT_HEADER}\n\n${blocks.join("\n\n")}\n`;
}

/** An `output` block followed by a blank line. */
export function output(name: string, value: string): string[] {
  return [`output "${name}" {`, `  value = ${value}`, "}", ""];
}

/** A sensitive `output` block followed by a blank line; the engines hide its value in plans. */
export function sensitiveOutput(name: string, value: string): string[] {
  return [`output "${name}" {`, `  value     = ${value}`, "  sensitive = true", "}", ""];
}
